(395498, 34459, 2170, '<td valign="top">The loss of detail at the base of the lamp is disappointing, but the shot is well-thought-out and lovely.</td>', 'The loss of detail at the base of the lamp is disappointing, but the shot is well-thought-out and lovely.', '2003-08-22 00:41:26.000000', NULL, 1),
(395500, 34498, 2170, '<td valign="top">I haven''t checked ESPN today, but don''t they still play baseball?  Just kiddin''.<br/> <br/>Oh yeah...nice photo.  :)</td>', 'I haven''t checked ESPN today, but don''t they still play baseball?  Just kiddin''. Oh yeah...nice photo.  :)', '2003-08-22 00:42:20.000000', NULL, 1),
