(395529, 34281, 4494, '<td valign="top">This shot has a "painting" look and feel to it.  I think you got lucky on the colors.  Great shot, nice composition.  8.</td>', 'This shot has a "painting" look and feel to it.  I think you got lucky on the colors.  Great shot, nice composition.  8.', '2003-08-22 01:17:24.000000', NULL, 1),
(395530, 34481, 11134, '<td valign="top">I''m usually hesitant about pictures that only convey the challenge once the title has been read.   Excellent composition, but it seems slightly blurry, and I don''t know about the choice of subjects...</td>', 'I''m usually hesitant about pictures that only convey the challenge once the title has been read.   Excellent composition, but it seems slightly blurry, and I don''t know about the choice of subjects...', '2003-08-22 01:17:43.000000', NULL, 1),
(395531, 33406, 4494, '<td valign="top">You didn''t take any chances on the orientation I see.  I wouldn''t have marked down for it anyway.  Really great shot straight out of the camera.  Wow, just think if you DID use your software.  8!</td>', 'You didn''t take any chances on the orientation I see.  I wouldn''t have marked down for it anyway.  Really great shot straight out of the camera.  Wow, just think if you DID use your software.  8!', '2003-08-22 01:19:39.000000', NULL, 1),
