(397865, 34440, 280, '<td valign="top">Good capture although it is a shame the in camera sepia modes seem to lack contrast.</td>', 'Good capture although it is a shame the in camera sepia modes seem to lack contrast.', '2003-08-24 17:51:33.000000', NULL, 1),
(397866, 34120, 280, '<td valign="top">I dont think the sepia tone works very well straight out of the camera, this shot seems to lack contrast. May have been better had you just used colour, as the subject looks quite rustic anyway.</td>', 'I dont think the sepia tone works very well straight out of the camera, this shot seems to lack contrast. May have been better had you just used colour, as the subject looks quite rustic anyway.', '2003-08-24 17:52:16.000000', NULL, 1),
