(398800, 33707, 7800, '<td valign="top">Nice color, cropped a little too tightly.</td>', 'Nice color, cropped a little too tightly.', '2003-08-25 15:03:09.000000', NULL, 1),
(398802, 34284, 7703, '<td valign="top">I think this is out of focus</td>', 'I think this is out of focus', '2003-08-25 15:09:50.000000', NULL, 1),
(398826, 34327, 7033, '<td valign="top">Nice approach to the challenge... Makes the viewer think about the past rather than simply being shown something from the past.  I love the dreamy effect imparted by the combination of mist and sunlight.  --9</td>', 'Nice approach to the challenge... Makes the viewer think about the past rather than simply being shown something from the past.  I love the dreamy effect imparted by the combination of mist and sunlight.  --9', '2003-08-25 15:42:36.000000', NULL, 1),
(398835, 34431, 7033, '<td valign="top">Truly beautiful image!  I especially love the rich colors and subdued tones-- it really creates a mood suitable for the subject.  --10</td>', 'Truly beautiful image!  I especially love the rich colors and subdued tones-- it really creates a mood suitable for the subject.  --10', '2003-08-25 15:57:25.000000', NULL, 1),
(398841, 34485, 7033, '<td valign="top">Nice image... definitely hearkens back to another era!  Composition and placement of the sextant works pretty well for me, but the lighting (yellow cast) is just a bit too much for the shot, in my opinion.  Focus on the stopwatch seems a bit soft, as well.  --7</td>', 'Nice image... definitely hearkens back to another era!  Composition and placement of the sextant works pretty well for me, but the lighting (yellow cast) is just a bit too much for the shot, in my opinion.  Focus on the stopwatch seems a bit soft, as well.  --7', '2003-08-25 16:03:34.000000', NULL, 1),
(398844, 34496, 7033, '<td valign="top">Beautiful image... natural framing provided by the tree is especially nice.  Seems like a bit of a stretch for the challenge, though.  --8</td>', 'Beautiful image... natural framing provided by the tree is especially nice.  Seems like a bit of a stretch for the challenge, though.  --8', '2003-08-25 16:05:39.000000', NULL, 1),
(398876, 34231, 6888, '<td valign="top">nice composition, would like to have seen more detail in the lettering on the front of thse train, and that unfortunate white spot on the lower left...</td>', 'nice composition, would like to have seen more detail in the lettering on the front of thse train, and that unfortunate white spot on the lower left...', '2003-08-25 16:33:28.000000', NULL, 1),
(398880, 34135, 6888, '<td valign="top">try as i might, i am having a hard time linking this to the past...i know its an older house and all...just doesnt grab me for this challenge, sorry</td>', 'try as i might, i am having a hard time linking this to the past...i know its an older house and all...just doesnt grab me for this challenge, sorry', '2003-08-25 16:39:22.000000', NULL, 1),
