(399153, 34434, 11134, '<td valign="top">Wow, very nice.  Excellent composition, great colors, very well laid out.  I like the theme, but there seems to be something missing... so 9.</td>', 'Wow, very nice.  Excellent composition, great colors, very well laid out.  I like the theme, but there seems to be something missing... so 9.', '2003-08-25 21:24:50.000000', NULL, 1),
(399155, 34500, 11134, '<td valign="top">good composition, though the fact there is a cemetery shot in almost every challenge recently is rather upsetting...  i like the way the path makes you follow the grave stones out of the picture frame</td>', 'good composition, though the fact there is a cemetery shot in almost every challenge recently is rather upsetting...  i like the way the path makes you follow the grave stones out of the picture frame', '2003-08-25 21:28:47.000000', NULL, 1),
(399159, 34431, 11073, '<td valign="top">nice shot, like the depth of focus, and the nice composition.</td>', 'nice shot, like the depth of focus, and the nice composition.', '2003-08-25 21:44:02.000000', NULL, 1),
(399161, 34477, 11134, '<td valign="top">Excellent idea, great subject, perfect picture.  I can''t really think of a suggestion to make this better in my opinion.  Great job.</td>', 'Excellent idea, great subject, perfect picture.  I can''t really think of a suggestion to make this better in my opinion.  Great job.', '2003-08-25 21:46:08.000000', NULL, 1),
(399163, 34468, 11134, '<td valign="top">this is a good idea for a subject, but unfortunately there''s not much to it.  i think something in the background or maybe using the rule of thirds to put the subject in a corner would have made a significant improvement.</td>', 'this is a good idea for a subject, but unfortunately there''s not much to it.  i think something in the background or maybe using the rule of thirds to put the subject in a corner would have made a significant improvement.', '2003-08-25 21:50:14.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(399164, 34440, 11073, '<td valign="top">i would maybe zoom in on the subject a little - too much negative space up top in my opinion - maybe take the picture from a lower angle to emphasize the "power" of his swing. just some thoughts. cool pic and good idea. felling a tree is definately from the past! :) nice work.</td>', 'i would maybe zoom in on the subject a little - too much negative space up top in my opinion - maybe take the picture from a lower angle to emphasize the "power" of his swing. just some thoughts. cool pic and good idea. felling a tree is definately from the past! :) nice work.', '2003-08-25 21:51:51.000000', NULL, 1),
(399170, 34493, 11073, '<td valign="top">i think that that the stadium lights, etc. on the ground distract my eye a little too much - i know it couldn''t be avoided to get the sunset - but maybe try a different angle for a "cleaner" shot.  That said, I''m focusing my score on the plane and the intent, not the afformentioned comment.  I love the angle, and the composition, it gives a "feeling" of movement. Almost like the plane is taking off into the sunset. Anyone with at least a little appreciation for planes ( or has seen pearl harbor) can tell by the cockpit that it''s an old plane from the past. nice shot.</td>', 'i think that that the stadium lights, etc. on the ground distract my eye a little too much - i know it couldn''t be avoided to get the sunset - but maybe try a different angle for a "cleaner" shot.  That said, I''m focusing my score on the plane and the intent, not the afformentioned comment.  I love the angle, and the composition, it gives a "feeling" of movement. Almost like the plane is taking off into the sunset. Anyone with at least a little appreciation for planes ( or has seen pearl harbor) can tell by the cockpit that it''s an old plane from the past. nice shot.', '2003-08-25 21:57:55.000000', NULL, 1),
(399172, 34486, 11073, '<td valign="top">some might not immediately recognize the tractor as old...but i do...nice shot.</td>', 'some might not immediately recognize the tractor as old...but i do...nice shot.', '2003-08-25 22:00:13.000000', NULL, 1),
(399173, 34184, 11073, '<td valign="top">you might try to move the camera position a few inches to the right horizontally to frame the teepee (sp?) on the right with the one on the left. that said, it''s a cool picture. nice work.</td>', 'you might try to move the camera position a few inches to the right horizontally to frame the teepee (sp?) on the right with the one on the left. that said, it''s a cool picture. nice work.', '2003-08-25 22:01:58.000000', NULL, 1),
(399184, 34234, 11073, '<td valign="top">too bad you can''t crop out the "bodyless" right arm - that would have allowed me to give a higher score. as it is "the arm" makes it too much like a snap shot to me.  Everything else i like.  Nice timing to capture good emotions on your subjects.</td>', 'too bad you can''t crop out the "bodyless" right arm - that would have allowed me to give a higher score. as it is "the arm" makes it too much like a snap shot to me.  Everything else i like.  Nice timing to capture good emotions on your subjects.', '2003-08-25 22:08:31.000000', NULL, 1),
(399186, 34220, 11073, '<td valign="top">other than the table "ending" in the top left...i like it.</td>', 'other than the table "ending" in the top left...i like it.', '2003-08-25 22:09:36.000000', NULL, 1),
(399188, 34418, 11073, '<td valign="top">a little bright...i can tell by the shadow that you were taking in the direction of the sun...maybe try it with the sun more to your back.  I also might either center the tractor more or give some negative space in front of it instead of behind.  Comments aside, it''s a cool picture and a nice subject.</td>', 'a little bright...i can tell by the shadow that you were taking in the direction of the sun...maybe try it with the sun more to your back.  I also might either center the tractor more or give some negative space in front of it instead of behind.  Comments aside, it''s a cool picture and a nice subject.', '2003-08-25 22:11:44.000000', NULL, 1),
(399195, 33550, 11073, '<td valign="top">i think i would like to see the statues backing cropped out - but that''s just a minor gripe - cool picture.</td>', 'i think i would like to see the statues backing cropped out - but that''s just a minor gripe - cool picture.', '2003-08-25 22:18:18.000000', NULL, 1),
(399203, 34494, 11073, '<td valign="top">good use of closing in on subject.  cool shot. i was just thinking that there weren''t enough close ups in this challenge....:)</td>', 'good use of closing in on subject.  cool shot. i was just thinking that there weren''t enough close ups in this challenge....:)', '2003-08-25 22:25:24.000000', NULL, 1),
(399205, 33624, 11073, '<td valign="top">awesome shot. nice work.</td>', 'awesome shot. nice work.', '2003-08-25 22:27:07.000000', NULL, 1),
(399207, 34477, 11073, '<td valign="top">very cool shot and interpretation of category.</td>', 'very cool shot and interpretation of category.', '2003-08-25 22:28:53.000000', NULL, 1),
(399214, 33761, 11073, '<td valign="top">In the Beginning...or Blackbear from negative space 2 challenge....or...nevermind.  Good interpretation? yes.  Enough to compensate for other criterea such as composition, lighting, dof, etc.? Sorry.</td>', 'In the Beginning...or Blackbear from negative space 2 challenge....or...nevermind.  Good interpretation? yes.  Enough to compensate for other criterea such as composition, lighting, dof, etc.? Sorry.', '2003-08-25 22:35:24.000000', NULL, 1),
