(399220, 34105, 11073, '<td valign="top">nice interpretation</td>', 'nice interpretation', '2003-08-25 22:38:34.000000', NULL, 1),
(399230, 34110, 11073, '<td valign="top">great shot, subject, and perspective.  The road and the angle of the shot gives it "movement" very cool.</td>', 'great shot, subject, and perspective.  The road and the angle of the shot gives it "movement" very cool.', '2003-08-25 22:53:53.000000', NULL, 1),
