(400360, 34476, 10414, '<td valign="top">A wonderful piece of the past, and a wonderful shot!!!!    10</td>', 'A wonderful piece of the past, and a wonderful shot!!!!    10', '2003-08-27 00:30:54.000000', NULL, 1),
(400442, 34489, 8445, '<td valign="top">This is a really good pic dad!</td>', 'This is a really good pic dad!', '2003-08-27 01:29:26.000000', NULL, 1),
(400614, 34482, 9387, '<td valign="top">I like the photo but something keeps drawing me back to think that it almost isn''t complete.  Odd view that I find disturbing.</td>', 'I like the photo but something keeps drawing me back to think that it almost isn''t complete.  Odd view that I find disturbing.', '2003-08-27 02:24:05.000000', NULL, 1),
(400615, 33828, 9387, '<td valign="top">Would have liked it better without the lens flare.</td>', 'Would have liked it better without the lens flare.', '2003-08-27 02:24:30.000000', NULL, 1),
(400618, 34473, 9387, '<td valign="top">I like this photo.</td>', 'I like this photo.', '2003-08-27 02:24:51.000000', NULL, 1),
(400619, 33406, 9387, '<td valign="top">I''d rather that you flipped it for me.</td>', 'I''d rather that you flipped it for me.', '2003-08-27 02:25:21.000000', NULL, 1),
(400621, 33839, 9387, '<td valign="top">Was the fun of the past drinking or playing bottle caps?</td>', 'Was the fun of the past drinking or playing bottle caps?', '2003-08-27 02:25:57.000000', NULL, 1),
(400622, 34120, 9387, '<td valign="top">I like the photo a lot but the left side is a little too washed out.</td>', 'I like the photo a lot but the left side is a little too washed out.', '2003-08-27 02:26:50.000000', NULL, 1),
(400626, 34237, 9387, '<td valign="top">a little too dark.</td>', 'a little too dark.', '2003-08-27 02:27:17.000000', NULL, 1),
(400627, 34380, 9387, '<td valign="top">Where did you dredge this glave up from?  Good going.</td>', 'Where did you dredge this glave up from?  Good going.', '2003-08-27 02:27:45.000000', NULL, 1),
(400629, 34449, 9387, '<td valign="top">Good idea but I would have liked it portrayed better.</td>', 'Good idea but I would have liked it portrayed better.', '2003-08-27 02:28:43.000000', NULL, 1),
(400630, 34476, 9387, '<td valign="top">Love the picture.</td>', 'Love the picture.', '2003-08-27 02:29:00.000000', NULL, 1),
(400632, 34455, 9387, '<td valign="top">good idea.</td>', 'good idea.', '2003-08-27 02:29:46.000000', NULL, 1),
(400633, 34110, 9387, '<td valign="top">nice truck</td>', 'nice truck', '2003-08-27 02:30:05.000000', NULL, 1),
(400634, 33685, 9387, '<td valign="top">haven''t sen one of those signs for awhile.</td>', 'haven''t sen one of those signs for awhile.', '2003-08-27 02:30:31.000000', NULL, 1),
(400639, 33579, 9387, '<td valign="top">Great!</td>', 'Great!', '2003-08-27 02:31:08.000000', NULL, 1),
(400643, 34499, 9387, '<td valign="top">good composition</td>', 'good composition', '2003-08-27 02:32:19.000000', NULL, 1),
(400646, 33656, 9387, '<td valign="top">I like the picture and the idea but the light coming in that big window is disturbing.  If you could have changed your angle of view it might have been better.</td>', 'I like the picture and the idea but the light coming in that big window is disturbing.  If you could have changed your angle of view it might have been better.', '2003-08-27 02:33:50.000000', NULL, 1),
(400649, 34371, 9387, '<td valign="top">I wish the photo were a little lighter or is it my computer screen?</td>', 'I wish the photo were a little lighter or is it my computer screen?', '2003-08-27 02:34:27.000000', NULL, 1),
(400651, 34474, 9387, '<td valign="top">Good thinking and nice picture.</td>', 'Good thinking and nice picture.', '2003-08-27 02:34:55.000000', NULL, 1),
(400656, 33684, 9387, '<td valign="top">Good for something old but what does the title have to do with the picture.  Just curious.</td>', 'Good for something old but what does the title have to do with the picture.  Just curious.', '2003-08-27 02:37:22.000000', NULL, 1),
(400808, 34105, 11412, '<td valign="top">I like the composition, colouring and clarity.</td>', 'I like the composition, colouring and clarity.', '2003-08-27 07:00:45.000000', NULL, 1),
(401170, 34474, 7711, '<td valign="top">;) I recognize that handsome devil! Beautiful emotion in this shot, love the expression on his face.</td>', ';) I recognize that handsome devil! Beautiful emotion in this shot, love the expression on his face.', '2003-08-27 12:02:09.000000', NULL, 1),
(401382, 34421, 10263, '<td valign="top">I love the tones in this one.  1757 is certainly the past :)</td>', 'I love the tones in this one.  1757 is certainly the past :)', '2003-08-27 13:46:31.000000', NULL, 1),
(401387, 34205, 10263, '<td valign="top">I would have liked this better with less foreground.</td>', 'I would have liked this better with less foreground.', '2003-08-27 13:47:47.000000', NULL, 1),
(401388, 34482, 10263, '<td valign="top">This is nice. Love the muted tones and the pattern in the background really sets it off.</td>', 'This is nice. Love the muted tones and the pattern in the background really sets it off.', '2003-08-27 13:48:41.000000', NULL, 1),
(401391, 33815, 10263, '<td valign="top">It would be nice to see the colors here.</td>', 'It would be nice to see the colors here.', '2003-08-27 13:50:26.000000', NULL, 1),
(401393, 34485, 10263, '<td valign="top">Nice composition and interesting subject. The focus could be better.</td>', 'Nice composition and interesting subject. The focus could be better.', '2003-08-27 13:51:41.000000', NULL, 1),
(401396, 33828, 10263, '<td valign="top">Love the spot of sunlight coming through. The branch on the right seems wrong. I think it should have showed more or none at all.</td>', 'Love the spot of sunlight coming through. The branch on the right seems wrong. I think it should have showed more or none at all.', '2003-08-27 13:53:52.000000', NULL, 1),
(401403, 34496, 10263, '<td valign="top">Beautiful sunset. You did a great capture of the sun on the water. I like how the dead branch on the bottom left balances the branches on top right. Good job</td>', 'Beautiful sunset. You did a great capture of the sun on the water. I like how the dead branch on the bottom left balances the branches on top right. Good job', '2003-08-27 13:56:08.000000', NULL, 1),
(401408, 34455, 10263, '<td valign="top">Too much foreground for me. I would like to see a close up of the old barn</td>', 'Too much foreground for me. I would like to see a close up of the old barn', '2003-08-27 13:57:28.000000', NULL, 1),
(401414, 33761, 10263, '<td valign="top">.....God created the heavens and the earth. Where are they? 1 point for the title.</td>', '.....God created the heavens and the earth. Where are they? 1 point for the title.', '2003-08-27 13:59:23.000000', NULL, 1),
(401427, 34336, 10263, '<td valign="top">It is a little too dark. The concept is wonderful. There should have been something to show the cross in greater contrast to the building. Different lighting maybe. I would like to see some different shots of this because I love the feel behind it. Makes me want to know more.</td>', 'It is a little too dark. The concept is wonderful. There should have been something to show the cross in greater contrast to the building. Different lighting maybe. I would like to see some different shots of this because I love the feel behind it. Makes me want to know more.', '2003-08-27 14:03:58.000000', NULL, 1),
(401437, 34497, 10263, '<td valign="top">I love this building! Fits the subject. Keeps my interest.. makes me feel something.. makes me want to know more about it.</td>', 'I love this building! Fits the subject. Keeps my interest.. makes me feel something.. makes me want to know more about it.', '2003-08-27 14:07:15.000000', NULL, 1),
(401475, 34474, 10263, '<td valign="top">Beautiful.. sentimental and moving. I love the way he is looking at her (he still loves her) and I like the photos reflected in the mirror on the wall.</td>', 'Beautiful.. sentimental and moving. I love the way he is looking at her (he still loves her) and I like the photos reflected in the mirror on the wall.', '2003-08-27 14:18:52.000000', NULL, 1),
(401482, 33921, 10263, '<td valign="top">OK we need a tutorial of how you did that in-camera. Love the tones</td>', 'OK we need a tutorial of how you did that in-camera. Love the tones', '2003-08-27 14:20:24.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(401492, 34275, 10263, '<td valign="top">My main consideration when I view a photo here is how much impact it has on my emotions. This one hit me hard in the pit of my stomach and brought tears to my eyes. 10</td>', 'My main consideration when I view a photo here is how much impact it has on my emotions. This one hit me hard in the pit of my stomach and brought tears to my eyes. 10', '2003-08-27 14:23:29.000000', NULL, 1),
(401556, 34380, 10263, '<td valign="top">Fits the challenge well. Beautiful shot. 9</td>', 'Fits the challenge well. Beautiful shot. 9', '2003-08-27 14:54:04.000000', NULL, 1),
(401563, 34284, 10263, '<td valign="top">This fits the challenge but it is out of focus. The grass seems over exposed.</td>', 'This fits the challenge but it is out of focus. The grass seems over exposed.', '2003-08-27 14:56:14.000000', NULL, 1),
(401569, 34418, 10263, '<td valign="top">The subject fits the challenge but it is a bit out of focus and over exposed. I would prefer a tighter shot of the tractor</td>', 'The subject fits the challenge but it is a bit out of focus and over exposed. I would prefer a tighter shot of the tractor', '2003-08-27 14:57:45.000000', NULL, 1),
(401581, 34234, 10263, '<td valign="top">This just feels like a snapshot with not a lot of atristic value. The arm on the right should have a body attached to it :) There is too much going on to really have a focal point. They do look like they are having fun though.</td>', 'This just feels like a snapshot with not a lot of atristic value. The arm on the right should have a body attached to it :) There is too much going on to really have a focal point. They do look like they are having fun though.', '2003-08-27 15:01:37.000000', NULL, 1),
(401842, 34092, 11570, '<td valign="top">A beautiful study at the precious time of a baby''s life.<br/> <br/>I like the soft filtration of colour with the crispness of the image overall - excellent.</td>', 'A beautiful study at the precious time of a baby''s life. I like the soft filtration of colour with the crispness of the image overall - excellent.', '2003-08-27 18:18:16.000000', NULL, 1),
(401844, 33815, 11651, '<td valign="top">Great B &amp; W....</td>', 'Great B & W....', '2003-08-27 18:18:52.000000', NULL, 1),
(401904, 34449, 9437, '<td valign="top">While the sepia tone does evoke the past, I would have preferred to be able to read the headstone.</td>', 'While the sepia tone does evoke the past, I would have preferred to be able to read the headstone.', '2003-08-27 19:11:19.000000', NULL, 1),
(401908, 34483, 9437, '<td valign="top">This low key photo is well done. I like that the label is readable and the simplicity of 4 basic colors contributes to the overall aesthetic.</td>', 'This low key photo is well done. I like that the label is readable and the simplicity of 4 basic colors contributes to the overall aesthetic.', '2003-08-27 19:13:56.000000', NULL, 1),
(401914, 33819, 9437, '<td valign="top">The color is what caught my eye first. It''s lovely. The composition could be a bit cleaner though. The cars and telephone lines in the background are distracting.</td>', 'The color is what caught my eye first. It''s lovely. The composition could be a bit cleaner though. The cars and telephone lines in the background are distracting.', '2003-08-27 19:18:18.000000', NULL, 1),
(401917, 33435, 9437, '<td valign="top">I was going to say that the subject was too centered for my taste. Then when the photo enlarged I saw the gentlman sitting on the porch. It rescued the composition. Well done.</td>', 'I was going to say that the subject was too centered for my taste. Then when the photo enlarged I saw the gentlman sitting on the porch. It rescued the composition. Well done.', '2003-08-27 19:21:37.000000', NULL, 1),
(402002, 33684, 1202, '<td valign="top">? 5</td>', '? 5', '2003-08-27 21:17:36.000000', NULL, 1),
(402142, 33684, 8911, '<td valign="top">A nice photo, very plain and stark, though I had to blink at the title a few times. :)</td>', 'A nice photo, very plain and stark, though I had to blink at the title a few times. :)', '2003-08-28 00:25:04.000000', NULL, 1),
(402151, 33501, 8911, '<td valign="top">Were you trying to get the detail of the eye in spite of the lighting? Unfortunately, so much of your subject is washed out / blasted out by the light that it doesn''t work very well....</td>', 'Were you trying to get the detail of the eye in spite of the lighting? Unfortunately, so much of your subject is washed out / blasted out by the light that it doesn''t work very well....', '2003-08-28 00:32:35.000000', NULL, 1),
(402154, 33425, 8911, '<td valign="top">I''m afraid I can''t really tell what this is, let alone whether it''s old or new, past or present. It just looks like metal, some fabric, maybe some plastic - hard to be sure. Very crisp focus.</td>', 'I''m afraid I can''t really tell what this is, let alone whether it''s old or new, past or present. It just looks like metal, some fabric, maybe some plastic - hard to be sure. Very crisp focus.', '2003-08-28 00:33:39.000000', NULL, 1),
(402156, 34418, 8911, '<td valign="top">Nice choice of subject, and I like the slightly off-center composition. The lighting''s a bit bright, and focus seems to be on the weeds in the foreground rather than the tractor, however.</td>', 'Nice choice of subject, and I like the slightly off-center composition. The lighting''s a bit bright, and focus seems to be on the weeds in the foreground rather than the tractor, however.', '2003-08-28 00:34:41.000000', NULL, 1),
(402158, 34455, 8911, '<td valign="top">This is a nice little scene. It appears to have some compression artifacts (along the roof lines, power lines, etc.) - and as far as I can tell, focus is on the foreground right, fence and grass...not quite sure why.</td>', 'This is a nice little scene. It appears to have some compression artifacts (along the roof lines, power lines, etc.) - and as far as I can tell, focus is on the foreground right, fence and grass...not quite sure why.', '2003-08-28 00:36:20.000000', NULL, 1),
(402161, 34496, 8911, '<td valign="top">This is a really gorgeous sunset picture - soft, but not too soft, and the lighting effects were captured wonderfully.</td>', 'This is a really gorgeous sunset picture - soft, but not too soft, and the lighting effects were captured wonderfully.', '2003-08-28 00:37:35.000000', NULL, 1),
(402168, 34506, 8911, '<td valign="top">This is a well-framed and interesting shot; it seems to suffer from the JPG compression, though, with little jaggies on all the angled and curved lines (swingset in the background, diamonds along the wall, tiles, tables, chairs...). It''s only half the maximum file size (which is 150 k), so you might want to try to use bigger files in future challenges, for higher quality.</td>', 'This is a well-framed and interesting shot; it seems to suffer from the JPG compression, though, with little jaggies on all the angled and curved lines (swingset in the background, diamonds along the wall, tiles, tables, chairs...). It''s only half the maximum file size (which is 150 k), so you might want to try to use bigger files in future challenges, for higher quality.', '2003-08-28 00:42:30.000000', NULL, 1),
(402173, 33739, 8911, '<td valign="top">This is a nice shot. I''d love to see, after the challenge, what it would look like with a bit of sharping, and some extra filters to keep the jaggies along the rooftops down (not sure if that can be accomplished in such dramatic lighting, though).</td>', 'This is a nice shot. I''d love to see, after the challenge, what it would look like with a bit of sharping, and some extra filters to keep the jaggies along the rooftops down (not sure if that can be accomplished in such dramatic lighting, though).', '2003-08-28 00:45:41.000000', NULL, 1),
(402174, 34459, 8911, '<td valign="top">This is a very evocative photo - I like the crisp clarity that black and white gives it.</td>', 'This is a very evocative photo - I like the crisp clarity that black and white gives it.', '2003-08-28 00:47:00.000000', NULL, 1),
(402177, 34281, 8911, '<td valign="top">A wonderfully sweet image, feels very much like opening a door into the past. There''s a hint of softness to the woman, as if she moved a little while the photograph was being taken; with everything else so crisp, it''s a minor distraction from a lovely photo.</td>', 'A wonderfully sweet image, feels very much like opening a door into the past. There''s a hint of softness to the woman, as if she moved a little while the photograph was being taken; with everything else so crisp, it''s a minor distraction from a lovely photo.', '2003-08-28 00:47:53.000000', NULL, 1),
(402179, 34431, 8911, '<td valign="top">Perfect lighting and focus for a shot like this...a memory-lane sort of feel. Very nice.</td>', 'Perfect lighting and focus for a shot like this...a memory-lane sort of feel. Very nice.', '2003-08-28 00:48:32.000000', NULL, 1),
(402182, 33860, 8911, '<td valign="top">This is a lovely photograph - I especially like the way it''s taken against the stacked firewood, a perfect background for the tone you''re creating. The wrap is an especially nice touch, drawing the eye back to the man rather than letting attention wander too randomly about.</td>', 'This is a lovely photograph - I especially like the way it''s taken against the stacked firewood, a perfect background for the tone you''re creating. The wrap is an especially nice touch, drawing the eye back to the man rather than letting attention wander too randomly about.', '2003-08-28 00:50:19.000000', NULL, 1),
(402183, 34105, 8911, '<td valign="top">The date and the choice of pen are a nice touch. Not sure if the pen really would have looked just that way or not (looks a little too crisp to me, but I don''t know pens through history), but the feel of it is just right. This is great.</td>', 'The date and the choice of pen are a nice touch. Not sure if the pen really would have looked just that way or not (looks a little too crisp to me, but I don''t know pens through history), but the feel of it is just right. This is great.', '2003-08-28 00:51:20.000000', NULL, 1),
(402185, 34451, 8911, '<td valign="top">A great shot. Just enough space above and below to frame the boats, and you let them dominate the picture as they should. The lines are nicely crisp, especially considering that''s without any sharping edits available. A hint of compression artifacts on the edges of the rolled sails, maybe in the water (not sure) and at the bow of the white boat, but fairly minor - not the kind that jump out of you.</td>', 'A great shot. Just enough space above and below to frame the boats, and you let them dominate the picture as they should. The lines are nicely crisp, especially considering that''s without any sharping edits available. A hint of compression artifacts on the edges of the rolled sails, maybe in the water (not sure) and at the bow of the white boat, but fairly minor - not the kind that jump out of you.', '2003-08-28 00:52:59.000000', NULL, 1),
(402187, 33921, 8911, '<td valign="top">I have to comment to this just so I remember to look at it later and see how you did this. It''s a beautiful photo, very evocative and good mood, and the tinting is perfect for it, as is the blur at the sides. Very much a memories-of-the-past hazy feel.</td>', 'I have to comment to this just so I remember to look at it later and see how you did this. It''s a beautiful photo, very evocative and good mood, and the tinting is perfect for it, as is the blur at the sides. Very much a memories-of-the-past hazy feel.', '2003-08-28 00:53:55.000000', NULL, 1),
(402192, 34504, 8911, '<td valign="top">This is a great shot - a good time to center, and I like the stair-step effect you got from this angle, as well. The sepia tone works well with this subject and the crisp focus.</td>', 'This is a great shot - a good time to center, and I like the stair-step effect you got from this angle, as well. The sepia tone works well with this subject and the crisp focus.', '2003-08-28 00:56:51.000000', NULL, 1),
(402195, 34476, 8911, '<td valign="top">I really like this image - the sheer beauty of the scene is substantial - but it does seem to have a fair number of jaggies along the horizontal lines of the building in particular.</td>', 'I really like this image - the sheer beauty of the scene is substantial - but it does seem to have a fair number of jaggies along the horizontal lines of the building in particular.', '2003-08-28 00:59:29.000000', NULL, 1),
(402196, 34105, 6405, '<td valign="top">Very well done Ursula,Bravo!!</td>', 'Very well done Ursula,Bravo!!', '2003-08-28 01:02:37.000000', NULL, 0),
(402197, 34431, 7504, '<td valign="top">Ben  this is an awesome photo!  I can almost smell the vinyl.  Great job!<br/></td>', 'Ben  this is an awesome photo!  I can almost smell the vinyl.  Great job!', '2003-08-28 01:03:46.000000', NULL, 0),
(402199, 33624, 10260, '<td valign="top">Congratulations on first place!  This is a beautiful photo, clean and sharp.</td>', 'Congratulations on first place!  This is a beautiful photo, clean and sharp.', '2003-08-28 01:05:32.000000', NULL, 0),
(402201, 34476, 10260, '<td valign="top">Congrats on your deserved ribbon.  This is a beautiful image.</td>', 'Congrats on your deserved ribbon.  This is a beautiful image.', '2003-08-28 01:07:26.000000', NULL, 0),
(402202, 34431, 4967, '<td valign="top">Ben this is an amazing photo... very artistic and awesome... wonderfully done especially because there was no post processing... wow!  Adding the photo to my favorites now :-).</td>', 'Ben this is an amazing photo... very artistic and awesome... wonderfully done especially because there was no post processing... wow!  Adding the photo to my favorites now :-).', '2003-08-28 01:09:37.000000', NULL, 0),
(402204, 34476, 7504, '<td valign="top">Way-to-go Karmat!!!  This is a great shot!</td>', 'Way-to-go Karmat!!!  This is a great shot!', '2003-08-28 01:10:36.000000', NULL, 0),
(402205, 34105, 10260, '<td valign="top">Very beautiful. I thought I''d made an earlier comment, but I see I didn''t.  I know this is a 10 in my eyes.</td>', 'Very beautiful. I thought I''d made an earlier comment, but I see I didn''t.  I know this is a 10 in my eyes.', '2003-08-28 01:11:13.000000', NULL, 0),
(402207, 34463, 10643, '<td valign="top">I couldn''t believe it when I saw a 1909 S in this good condition in this picture. I waited to see your description to find out if it was real. The rarest Lincoln cent there is, and you put it on the ground ... cringe! I kind of disagree with the other comments, though; yes, the cigarette butt and matchstick are unattractive, but that''s the point.</td>', 'I couldn''t believe it when I saw a 1909 S in this good condition in this picture. I waited to see your description to find out if it was real. The rarest Lincoln cent there is, and you put it on the ground ... cringe! I kind of disagree with the other comments, though; yes, the cigarette butt and matchstick are unattractive, but that''s the point.', '2003-08-28 01:12:33.000000', NULL, 0),
(402208, 34275, 4967, '<td valign="top">This is an amazing photo, and the only 10 I gave for the challenge, very very well done.  Really made me emotional.  Wish this would have placed a little higher.  Nice job. Many of my grandmothers family also were lost to this time period. VERY EVIL!  Good job on making a menacing looking photo.</td>', 'This is an amazing photo, and the only 10 I gave for the challenge, very very well done.  Really made me emotional.  Wish this would have placed a little higher.  Nice job. Many of my grandmothers family also were lost to this time period. VERY EVIL!  Good job on making a menacing looking photo.', '2003-08-28 01:12:55.000000', NULL, 0),
(402211, 33624, 8054, '<td valign="top">Way to go on 1st place! I had a feeling about this one!  :)</td>', 'Way to go on 1st place! I had a feeling about this one!  :)', '2003-08-28 01:18:46.000000', NULL, 0),
(402212, 34476, 5313, '<td valign="top">Congratulations, Karma!  That''s a wonderful photo!</td>', 'Congratulations, Karma!  That''s a wonderful photo!', '2003-08-28 01:18:57.000000', NULL, 0),
(402213, 34105, 5313, '<td valign="top">Wow!  This sure is a sign of the past, isn''t it?  Great job, Ursula!</td>', 'Wow!  This sure is a sign of the past, isn''t it?  Great job, Ursula!', '2003-08-28 01:19:55.000000', NULL, 0),
(402218, 33406, 7935, '<td valign="top">argh  when did they decide rotation was allowed because I watched that thread for a day or 2  oh well   another mid 5 for me</td>', 'argh  when did they decide rotation was allowed because I watched that thread for a day or 2  oh well   another mid 5 for me', '2003-08-28 01:25:33.000000', NULL, 0),
(402230, 34473, 6405, '<td valign="top">This is awesome shot!</td>', 'This is awesome shot!', '2003-08-28 01:39:36.000000', NULL, 0),
(402231, 34473, 7706, '<td valign="top">Not a bad score, congrats :)</td>', 'Not a bad score, congrats :)', '2003-08-28 01:39:50.000000', NULL, 0),
(402238, 34184, 4793, '<td valign="top">I took this photo on the Crow Indian reservation/Montana</td>', 'I took this photo on the Crow Indian reservation/Montana', '2003-08-28 01:46:44.000000', NULL, 0),
(402242, 33624, 3554, '<td valign="top">Congratulations on a solid first place. I loved this shot.</td>', 'Congratulations on a solid first place. I loved this shot.', '2003-08-28 01:47:30.000000', NULL, 0),
(402255, 34105, 3554, '<td valign="top">Congrats on the ribbon!</td>', 'Congrats on the ribbon!', '2003-08-28 01:59:39.000000', NULL, 0),
(402282, 33624, 6870, '<td valign="top">Very nice! Congratulations!</td>', 'Very nice! Congratulations!', '2003-08-28 02:30:37.000000', NULL, 0),
(402283, 34476, 6870, '<td valign="top">Such wonderful clarity and tones. A winner for sure!</td>', 'Such wonderful clarity and tones. A winner for sure!', '2003-08-28 02:31:49.000000', NULL, 0),
